#!/bin/zsh
# Writes app/ChumsWatch/HubConfig.swift from ~/.chums/config.json: the hub's public address, the watch's token and a
# build stamp. bin/chums-install runs it. The generated file is git-ignored (it holds the token).
# With "watchTokenRef" (bin/chums-token-ref) the token is read from 1Password (op read), else it is "watchToken";
# either is checked against "watchTokenHash" when that is set.
ROOT="${0:A:h:h}"
[[ -f ~/.chums/config.json ]] || { echo "no ~/.chums/config.json yet: start the hub once (bin/chums-hub), it writes one" >&2; exit 1 }
python3 - "$ROOT" <<'EOF'
import hashlib, json, os, subprocess, sys
root = sys.argv[1]
cfg = json.load(open(os.path.expanduser("~/.chums/config.json")))
if cfg.get('watchTokenRef'):
    account = ['--account', cfg['watchTokenAccount']] if cfg.get('watchTokenAccount') else []
    try: r = subprocess.run(['op', 'read', *account, cfg['watchTokenRef']], capture_output=True, text=True)
    except FileNotFoundError: sys.exit("watchTokenRef is set but the 1Password CLI isn't installed: brew install 1password-cli")
    token = r.stdout.rstrip('\n')
    if r.returncode or not token: sys.exit(f"op read {cfg['watchTokenRef']} failed: {r.stderr.strip() or 'empty'}")
else:
    token = cfg.get('watchToken') or sys.exit("no watchToken (or watchTokenRef) in ~/.chums/config.json: start the hub once, it writes one")
# a token the hub would refuse makes a watch app that can't connect
if cfg.get('watchTokenHash') and hashlib.sha256(token.encode()).hexdigest() != str(cfg['watchTokenHash']).lower():
    sys.exit("the watch token doesn't match watchTokenHash: run bin/chums-token-ref again, then restart the hub")
# The watch reaches the Mac only through its public https address (bin/chums-tunnel, cfg "publicURL"): watchOS doesn't
# support apps reaching a home-network address, and probing one on other networks would hand the token to whoever has
# that address. 127.0.0.1 is for the Simulator (the app drops it on a real watch).
hosts = [h for h in (cfg.get('publicURL'), f"http://127.0.0.1:{cfg['port']}") if h]
if not cfg.get('publicURL'): print("no publicURL yet: run bin/chums-tunnel first, or the watch can only reach the Simulator's hub")
import datetime
build = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
out = os.path.join(root, "app/ChumsWatch/HubConfig.swift")
# it holds the watch's token: readable by this user only
with os.fdopen(os.open(out, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600), "w") as f:
    os.fchmod(f.fileno(), 0o600)
    f.write("// Generated by tools/gen-config.sh. Do not commit.\n")
    f.write("enum HubConfig {\n")
    f.write(f"    static let hosts = {json.dumps(hosts)}\n")
    f.write(f"    static let token = {json.dumps(token)}   // the watch's own token: the watch API only\n")
    f.write(f"    static let build = {json.dumps(build)}\n")
    # the watch's frame rate and memory in the hub's log every 30 s: for working on the app, off unless asked for
    f.write(f"    static let diagnostics = {'true' if cfg.get('diagnostics') else 'false'}\n")
    f.write("}\n")
print("wrote", out, hosts)
EOF
